import{_ as t,o as i,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const h=JSON.parse('{"title":"Document Version and Maintenance Notes","description":"","frontmatter":{},"headers":[],"relativePath":"en/0099-文档版本与维护说明.md","filePath":"en/0099-文档版本与维护说明.md"}'),a={name:"en/0099-文档版本与维护说明.md"};function r(s,e,c,l,d,u){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="document-version-and-maintenance-notes" tabindex="-1">Document Version and Maintenance Notes <a class="header-anchor" href="#document-version-and-maintenance-notes" aria-label="Permalink to &quot;Document Version and Maintenance Notes&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document number</td><td>99</td></tr><tr><td>Module</td><td>Appendices and Reference Materials</td></tr><tr><td>Core keywords</td><td>version management, maintenance notes, document standards, changelog, setting maintenance</td></tr></tbody></table><h2 id="i-overview-of-the-document-system" tabindex="-1">I. Overview of the Document System <a class="header-anchor" href="#i-overview-of-the-document-system" aria-label="Permalink to &quot;I. Overview of the Document System&quot;">​</a></h2><p>The setting system of the Anchor Symbiotic Civilization consists of 100 Markdown documents, numbered from 00 to 99, divided into ten major modules, with 10 documents in each module. The document system takes SPEC.md (Document Generation Specification) as its hard constraint, takes &quot;00-Heng Yuan Zhou: Cosmic Overview&quot; as the general outline, develops each module&#39;s documents in detail from different dimensions, and finally uses the appendix documents 90–99 for indexing, summarization, and consolidation. The entire document system constitutes a complete setting knowledge base that is logically self-consistent, clearly layered, and mutually cross-referenced.</p><p>The design of the document system follows three major principles: &quot;modularity, structure, and extensibility.&quot; Modularity means that each document focuses on one specific topic and stands as an independent article; structure means that all documents follow a unified format specification for ease of reading and retrieval; extensibility means that the document system reserves ample room for expansion, allowing the continuous improvement of the settings through revising existing documents and adding new content.</p><h2 id="ii-version-numbering-rules" tabindex="-1">II. Version Numbering Rules <a class="header-anchor" href="#ii-version-numbering-rules" aria-label="Permalink to &quot;II. Version Numbering Rules&quot;">​</a></h2><p>The document system adopts a three-level version numbering rule of &quot;major version.minor version.revision number&quot;:</p><table tabindex="0"><thead><tr><th>Version level</th><th>Numbering rule</th><th>Trigger condition</th><th>Example</th></tr></thead><tbody><tr><td>Major version</td><td>Increments from 1</td><td>Major architectural adjustments to the document system, such as module redivision or changes to core settings</td><td>v1.0 → v2.0</td></tr><tr><td>Minor version</td><td>Increments from 0</td><td>Substantive revision of the core content of a document, or the addition of important new setting content</td><td>v1.0 → v1.1</td></tr><tr><td>Revision number</td><td>Increments from 0</td><td>Non-substantive modifications such as textual corrections, format adjustments, and terminology unification</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>The current overall version of the document system is v1.0, i.e., the first complete release. Each document records its own version number in its document information block, and the overall version number of the document system is uniformly recorded in this document.</p><h2 id="iii-review-of-document-format-specifications" tabindex="-1">III. Review of Document Format Specifications <a class="header-anchor" href="#iii-review-of-document-format-specifications" aria-label="Permalink to &quot;III. Review of Document Format Specifications&quot;">​</a></h2><p>All documents must follow the following unified format specifications (see SPEC.md for detailed specifications):</p><h3 id="_3-1-file-naming" tabindex="-1">3.1 File Naming <a class="header-anchor" href="#_3-1-file-naming" aria-label="Permalink to &quot;3.1 File Naming&quot;">​</a></h3><p>The file name format is <code>XX-Document Title.md</code>, where XX is a two-digit number from 00 to 99, and the title is in Chinese without spaces.</p><h3 id="_3-2-document-structure" tabindex="-1">3.2 Document Structure <a class="header-anchor" href="#_3-2-document-structure" aria-label="Permalink to &quot;3.2 Document Structure&quot;">​</a></h3><p>Each document must contain the following structural elements:</p><ol><li><strong>Level-one heading</strong>: the document title (consistent with the file name)</li><li><strong>Document information block</strong>: a table of number, module, and core keywords (3–5)</li><li><strong>Main body</strong>: at least 3 sections with level-two headings, using structured elements such as lists and tables</li><li><strong>Conclusion</strong>: a brief summary paragraph</li><li><strong>Related documents</strong>: listing 2–3 related document numbers and names</li></ol><h3 id="_3-3-word-count-requirement" tabindex="-1">3.3 Word Count Requirement <a class="header-anchor" href="#_3-3-word-count-requirement" aria-label="Permalink to &quot;3.3 Word Count Requirement&quot;">​</a></h3><p>The main body of each document shall be no less than 800 characters (excluding headings and meta-information).</p><h3 id="_3-4-writing-style" tabindex="-1">3.4 Writing Style <a class="header-anchor" href="#_3-4-writing-style" aria-label="Permalink to &quot;3.4 Writing Style&quot;">​</a></h3><ul><li>A serious, systematic setting-document style, similar to an encyclopedia/setting collection</li><li>Use unified terms such as &quot;Hengyuan Universe,&quot; &quot;Anchor,&quot; and &quot;Symbiosis&quot;</li><li>Newly added settings must be logically self-consistent with existing settings and conform to the principle of &quot;Reality as the Foundation, upgrading through laws&quot;</li></ul><h2 id="iv-maintenance-organization-and-responsibilities" tabindex="-1">IV. Maintenance Organization and Responsibilities <a class="header-anchor" href="#iv-maintenance-organization-and-responsibilities" aria-label="Permalink to &quot;IV. Maintenance Organization and Responsibilities&quot;">​</a></h2><h3 id="_4-1-setting-maintenance-committee" tabindex="-1">4.1 Setting Maintenance Committee <a class="header-anchor" href="#_4-1-setting-maintenance-committee" aria-label="Permalink to &quot;4.1 Setting Maintenance Committee&quot;">​</a></h3><p>The Setting Maintenance Committee is the highest maintenance body of the document system, composed of senior setting creators, logic verification experts, and user representatives. Its core responsibilities include:</p><ul><li>Reviewing the overall architecture of the document system and major revision plans</li><li>Reviewing major setting changes to ensure consistency with core settings</li><li>Arbitrating setting disputes and providing authoritative interpretations</li><li>Regularly organizing comprehensive setting consistency self-checks</li><li>Publishing overall version updates of the document system</li></ul><h3 id="_4-2-module-maintainers" tabindex="-1">4.2 Module Maintainers <a class="header-anchor" href="#_4-2-module-maintainers" aria-label="Permalink to &quot;4.2 Module Maintainers&quot;">​</a></h3><p>Each module designates one module maintainer, responsible for the daily maintenance of the 10 documents in that module. Their responsibilities include:</p><ul><li>Tracking the setting consistency of the documents within the module</li><li>Reviewing revision applications for documents within the module</li><li>Coordinating cross-references among documents within the module</li><li>Collecting user feedback and suggestions on the module&#39;s content</li><li>Regularly reporting the module&#39;s maintenance status to the Setting Maintenance Committee</li></ul><h3 id="_4-3-document-creators" tabindex="-1">4.3 Document Creators <a class="header-anchor" href="#_4-3-document-creators" aria-label="Permalink to &quot;4.3 Document Creators&quot;">​</a></h3><p>Any qualified creator may participate in the creation and revision of documents. The responsibilities of creators include:</p><ul><li>Creating or revising documents in accordance with the format specifications</li><li>Ensuring that created content passes the check of the Setting Contradiction Self-Check List</li><li>Attaching a detailed revision description when submitting revisions</li><li>Cooperating with the review work of maintainers and the Committee</li></ul><h2 id="v-revision-process" tabindex="-1">V. Revision Process <a class="header-anchor" href="#v-revision-process" aria-label="Permalink to &quot;V. Revision Process&quot;">​</a></h2><h3 id="_5-1-regular-revision-process" tabindex="-1">5.1 Regular Revision Process <a class="header-anchor" href="#_5-1-regular-revision-process" aria-label="Permalink to &quot;5.1 Regular Revision Process&quot;">​</a></h3><ol><li><strong>Submit an application</strong>: the creator submits a revision application to the module maintainer, including the document number to be revised, a description of the revision content, and the reasons for the revision.</li><li><strong>Module review</strong>: the module maintainer reviews the revision content, focusing on format specifications and intra-module consistency. After approval, it is submitted to the Setting Maintenance Committee.</li><li><strong>Committee approval</strong>: the Setting Maintenance Committee conducts the final review of the revision content, focusing on cross-module consistency and core-setting consistency.</li><li><strong>Execute the revision</strong>: after approval, the module maintainer or the original author executes the document revision.</li><li><strong>Version update</strong>: after the revision is completed, update the document version number and record it in the changelog of this document.</li><li><strong>Related-document synchronization</strong>: if the revision content affects other documents, the related documents must be revised in synchronization.</li></ol><h3 id="_5-2-emergency-revision-process" tabindex="-1">5.2 Emergency Revision Process <a class="header-anchor" href="#_5-2-emergency-revision-process" aria-label="Permalink to &quot;5.2 Emergency Revision Process&quot;">​</a></h3><p>For emergency situations where serious setting contradictions or errors are discovered, the emergency revision process may be initiated:</p><ol><li><strong>Emergency report</strong>: the discoverer immediately reports the problem to the Setting Maintenance Committee.</li><li><strong>Rapid review</strong>: the Committee completes the emergency review within 24 hours and provides a revision plan.</li><li><strong>Execute the revision</strong>: designate a dedicated person to execute the revision immediately.</li><li><strong>Retroactive documentation</strong>: after the revision is completed, retroactively record the revision application and review records.</li></ol><h3 id="_5-3-regular-comprehensive-revision" tabindex="-1">5.3 Regular Comprehensive Revision <a class="header-anchor" href="#_5-3-regular-comprehensive-revision" aria-label="Permalink to &quot;5.3 Regular Comprehensive Revision&quot;">​</a></h3><p>The Setting Maintenance Committee organizes a comprehensive revision of the document system once a year, including:</p><ul><li>A comprehensive setting consistency self-check</li><li>Centralized handling of user feedback</li><li>Unification and updating of the terminology system</li><li>Synchronized updating of index documents</li><li>Unified checking and correction of document formats</li></ul><h2 id="vi-changelog" tabindex="-1">VI. Changelog <a class="header-anchor" href="#vi-changelog" aria-label="Permalink to &quot;VI. Changelog&quot;">​</a></h2><h3 id="v1-0-first-complete-release" tabindex="-1">v1.0 (First Complete Release) <a class="header-anchor" href="#v1-0-first-complete-release" aria-label="Permalink to &quot;v1.0 (First Complete Release)&quot;">​</a></h3><ul><li>Completed the creation and release of all 100 documents</li><li>Established the complete document system architecture and format specifications</li><li>Completed content coverage of the ten major modules</li><li>Established the appendix index system (terminology dictionary, system index, law index, chronology, register of the Ten Thousand Races, figures and organizations, FAQ, self-check list, expansion suggestions, version notes)</li></ul><h3 id="area-for-recording-subsequent-version-updates" tabindex="-1">Area for Recording Subsequent Version Updates <a class="header-anchor" href="#area-for-recording-subsequent-version-updates" aria-label="Permalink to &quot;Area for Recording Subsequent Version Updates&quot;">​</a></h3><p>(Update content of subsequent versions will be appended and recorded here, including version number, release date, and summary of main update content)</p><h2 id="vii-document-citation-and-cross-reference-specifications" tabindex="-1">VII. Document Citation and Cross-Reference Specifications <a class="header-anchor" href="#vii-document-citation-and-cross-reference-specifications" aria-label="Permalink to &quot;VII. Document Citation and Cross-Reference Specifications&quot;">​</a></h2><h3 id="_7-1-internal-citations" tabindex="-1">7.1 Internal Citations <a class="header-anchor" href="#_7-1-internal-citations" aria-label="Permalink to &quot;7.1 Internal Citations&quot;">​</a></h3><p>Cross-references among documents use the format of &quot;document number-document title,&quot; for example, &quot;see Document 84 &#39;General Framework of Archaeological Protocols&#39;.&quot; When citing, it should be ensured that the cited document indeed exists and that the number and title are correct.</p><h3 id="_7-2-terminology-citations" tabindex="-1">7.2 Terminology Citations <a class="header-anchor" href="#_7-2-terminology-citations" aria-label="Permalink to &quot;7.2 Terminology Citations&quot;">​</a></h3><p>When a core term is first used, the corresponding entry in Document 90 &quot;The Glossary&quot; may be noted for reference. When the same term is used subsequently, no repeated notation is needed.</p><h3 id="_7-3-external-citations" tabindex="-1">7.3 External Citations <a class="header-anchor" href="#_7-3-external-citations" aria-label="Permalink to &quot;7.3 External Citations&quot;">​</a></h3><p>If real-world materials or fictional works outside the setting system need to be cited, the source should be noted, and it should be clearly stated that such citation is reference material under the principle of &quot;Reality as the Foundation,&quot; and does not represent the complete adoption of its content by the setting system.</p><h2 id="viii-quality-assurance-mechanisms" tabindex="-1">VIII. Quality Assurance Mechanisms <a class="header-anchor" href="#viii-quality-assurance-mechanisms" aria-label="Permalink to &quot;VIII. Quality Assurance Mechanisms&quot;">​</a></h2><h3 id="_8-1-setting-contradiction-self-check" tabindex="-1">8.1 Setting Contradiction Self-Check <a class="header-anchor" href="#_8-1-setting-contradiction-self-check" aria-label="Permalink to &quot;8.1 Setting Contradiction Self-Check&quot;">​</a></h3><p>All newly created and revised documents must pass all check items of Document 97 &quot;Setting Contradiction Self-Check List,&quot; including more than 40 checks in three major categories: core-setting consistency, cross-module logical consistency, and document format specifications.</p><h3 id="_8-2-cross-review" tabindex="-1">8.2 Cross-Review <a class="header-anchor" href="#_8-2-cross-review" aria-label="Permalink to &quot;8.2 Cross-Review&quot;">​</a></h3><p>Each document must undergo cross-review by at least one other creator before formal release, focusing on cross-module logical consistency and terminology uniformity.</p><h3 id="_8-3-user-feedback-mechanism" tabindex="-1">8.3 User Feedback Mechanism <a class="header-anchor" href="#_8-3-user-feedback-mechanism" aria-label="Permalink to &quot;8.3 User Feedback Mechanism&quot;">​</a></h3><p>The document system provides user feedback channels; users may submit feedback through the following ways:</p><ul><li>Reporting setting contradictions and logical errors</li><li>Raising issues of terminology inconsistency</li><li>Suggesting supplements or revisions to specific content</li><li>Pointing out format and textual errors</li></ul><p>All feedback is processed in categories by the module maintainers, and important feedback is submitted to the Setting Maintenance Committee for deliberation.</p><h3 id="_8-4-quarterly-consistency-report" tabindex="-1">8.4 Quarterly Consistency Report <a class="header-anchor" href="#_8-4-quarterly-consistency-report" aria-label="Permalink to &quot;8.4 Quarterly Consistency Report&quot;">​</a></h3><p>The Setting Maintenance Committee publishes a &quot;Setting Consistency Report&quot; every quarter, including:</p><ul><li>Setting contradictions discovered in the quarter and their handling</li><li>Statistics of document revisions in the quarter</li><li>Progress of terminology unification</li><li>Handling of user feedback</li><li>Maintenance plan for the next quarter</li></ul><h2 id="ix-document-storage-and-distribution" tabindex="-1">IX. Document Storage and Distribution <a class="header-anchor" href="#ix-document-storage-and-distribution" aria-label="Permalink to &quot;IX. Document Storage and Distribution&quot;">​</a></h2><h3 id="_9-1-storage-format" tabindex="-1">9.1 Storage Format <a class="header-anchor" href="#_9-1-storage-format" aria-label="Permalink to &quot;9.1 Storage Format&quot;">​</a></h3><p>All documents are stored in Markdown (.md) format, ensuring cross-platform readability and convenient version management. Documents use UTF-8 encoding, supporting Chinese and special characters.</p><h3 id="_9-2-directory-structure" tabindex="-1">9.2 Directory Structure <a class="header-anchor" href="#_9-2-directory-structure" aria-label="Permalink to &quot;9.2 Directory Structure&quot;">​</a></h3><p>Documents are uniformly stored in the <code>anchor-docs/</code> directory, with file names in the format of <code>XX-Document Title.md</code>. SPEC.md, as the specification file, is also stored in the same directory.</p><h3 id="_9-3-version-management" tabindex="-1">9.3 Version Management <a class="header-anchor" href="#_9-3-version-management" aria-label="Permalink to &quot;9.3 Version Management&quot;">​</a></h3><p>It is recommended to use version control systems such as Git for document version management, attaching detailed commit messages recording the revision content and reasons for each revision submission.</p><h3 id="_9-4-distribution-methods" tabindex="-1">9.4 Distribution Methods <a class="header-anchor" href="#_9-4-distribution-methods" aria-label="Permalink to &quot;9.4 Distribution Methods&quot;">​</a></h3><p>The document system may be distributed in the following ways:</p><ul><li>Packaged as a ZIP archive for download</li><li>Deployed as a static website for online browsing</li><li>Converted to PDF or EPUB format for reading</li><li>Imported into knowledge base systems for structured management</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The Document Version and Maintenance Notes are the &quot;administrative constitution&quot; of the setting system of the Anchor Symbiotic Civilization. It establishes the version rules, maintenance organization, revision process, quality assurance mechanisms, and storage and distribution methods of the document system, ensuring that this vast setting system composed of 100 documents can always maintain order and consistency in the course of continuous growth. A good setting system requires not only wonderful content, but also a sound maintenance mechanism to guarantee its long-term healthy development. This document is the core carrier of that mechanism.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (Setting Contradiction Self-Check List)</li><li>90-术语词典 (The Glossary)</li><li>00-衡元宙宇宙总览 (Heng Yuan Zhou: Cosmic Overview)</li></ul>',77)])])}const g=t(a,[["render",r]]);export{h as __pageData,g as default};
